INSERT INTO `animais` (`id`, `nome`, `nome_cientifico`, `status`, `status_class`, `tipo`, `regiao`, `bioma`, `imagem`, `habitat`, `comportamento`, `curiosidade`, `alimentacao`, `ameacas`, `taxon_id`, `imagem_fonte`, `imagem_credito`) VALUES
(1, 'Onça-Pintada', 'Panthera onca', 'Vulnerável', 'vulneravel', 'Mamífero', 'Norte, Centro-Oeste, Nordeste, Sudeste', 'Amazônia, Cerrado, Pantanal, Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/9482510/original.jpeg', 'Florestas tropicais, áreas próximas a rios e regiões de mata densa.', 'É solitária, territorial e possui grande habilidade para nadar.', 'É o maior felino das Américas.', 'Peixes, jacarés, capivaras, veados e outros animais.', 'Desmatamento, caça ilegal e redução de suas presas naturais.', 60794, 'iNaturalist', '(c) Miguel Álvaro Méndez, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/7321979'),
(2, 'Boto-Cor-de-Rosa', 'Inia geoffrensis', 'Em Perigo', 'em-perigo', 'Mamífero', 'Norte', 'Amazônia', 'https://inaturalist-open-data.s3.amazonaws.com/photos/12008956/original.jpg', 'Rios, lagos e áreas alagadas da Bacia Amazônica.', 'Vive geralmente sozinho ou em pequenos grupos e utiliza ecolocalização.', 'Sua coloração pode ficar mais rosada com a idade.', 'Peixes, crustáceos e pequenos animais aquáticos.', 'Poluição dos rios, pesca acidental, barragens e degradação do habitat.', 23410, 'iNaturalist', '(c) Kevin Schafer, some rights reserved (CC BY-NC-ND) | cc-by-nc-nd | https://www.inaturalist.org/observations/8919272'),
(3, 'Arara-Azul', 'Anodorhynchus hyacinthinus', 'Vulnerável', 'vulneravel', 'Ave', 'Norte, Centro-Oeste', 'Amazônia, Pantanal, Cerrado', 'https://inaturalist-open-data.s3.amazonaws.com/photos/9859091/original.jpg', 'Áreas de cerrado, matas e regiões do Pantanal com árvores grandes.', 'Forma casais e costuma permanecer com o mesmo parceiro por longos períodos.', 'É uma das maiores espécies de araras do mundo.', 'Sementes e frutos de palmeiras.', 'Tráfico de animais, perda de habitat e retirada de árvores usadas para nidificação.', 229981, 'iNaturalist', '(c) Greg Lasley, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/7553269'),
(4, 'Tuiuiú', 'Jabiru mycteria', 'Pouco preocupante', 'pouco-preocupante', 'Ave', 'Norte, Centro-Oeste, Nordeste', 'Amazônia, Pantanal, Cerrado, Caatinga', 'https://inaturalist-open-data.s3.amazonaws.com/photos/9867912/original.jpg', 'Áreas alagadas, margens de rios e campos próximos a áreas úmidas.', 'Costuma caminhar em águas rasas procurando alimento.', 'É considerado um dos símbolos do Pantanal.', 'Peixes, sapos, insetos, pequenos répteis e outros animais.', 'Alterações em áreas úmidas e perda de habitat.', 226197, 'iNaturalist', '(c) Greg Lasley, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/7559243'),
(5, 'Tamanduá-Bandeira', 'Myrmecophaga tridactyla', 'Vulnerável', 'vulneravel', 'Mamífero', 'Norte, Centro-Oeste, Nordeste, Sudeste', 'Amazônia, Cerrado, Pantanal, Caatinga, Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/226672087/original.jpg', 'Campos, cerrados, áreas abertas e regiões de vegetação variada.', 'É geralmente solitário e utiliza suas garras para abrir formigueiros.', 'Pode consumir milhares de formigas e cupins em um único dia.', 'Formigas e cupins.', 'Queimadas, atropelamentos, caça e perda de habitat.', 40390, 'iNaturalist', '(c) João Vitor Oliveira de Souza, some rights reserved (CC BY) | cc-by | https://www.inaturalist.org/observations/133105924'),
(6, 'Lobo-Guará', 'Chrysocyon brachyurus', 'Vulnerável', 'vulneravel', 'Mamífero', 'Centro-Oeste, Sudeste, Sul', 'Cerrado, Pantanal, Mata Atlântica, Pampa', 'https://inaturalist-open-data.s3.amazonaws.com/photos/600302287/original.jpg', 'Campos e áreas abertas, principalmente em regiões de Cerrado.', 'É solitário e possui hábitos principalmente crepusculares e noturnos.', 'É o maior canídeo da América do Sul.', 'Frutos, pequenos mamíferos, aves, répteis e insetos.', 'Perda de habitat, atropelamentos e doenças transmitidas por animais domésticos.', 74464, 'iNaturalist', '(c) KENNEDY BORGES, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/330973006'),
(7, 'Ema', 'Rhea americana', 'Pouco preocupante', 'pouco-preocupante', 'Ave', 'Norte, Nordeste, Centro-Oeste, Sudeste, Sul', 'Amazônia, Caatinga, Cerrado, Pantanal, Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/51885863/original.jpeg', 'Campos, cerrados e outras áreas abertas.', 'Não voa, mas consegue correr em alta velocidade.', 'É uma das maiores aves brasileiras que não voam.', 'Sementes, frutos, insetos e pequenos animais.', 'Caça, perda de habitat e atropelamentos.', 230139, 'iNaturalist', '(c) dyrk, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/33054921'),
(8, 'Mico-Leão-Dourado', 'Leontopithecus rosalia', 'Em Perigo', 'em-perigo', 'Mamífero', 'Sudeste', 'Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/4348421/original.jpeg', 'Florestas da Mata Atlântica.', 'Vive em grupos familiares e passa grande parte do tempo nas árvores.', 'Sua pelagem dourada é uma das características mais marcantes da espécie.', 'Frutos, insetos, pequenos vertebrados e néctar.', 'Desmatamento, fragmentação florestal e doenças.', 41039, 'iNaturalist', '(c) B. Phalan, some rights reserved (CC BY) | cc-by | https://www.inaturalist.org/observations/3740485'),
(9, 'Tatu-Bola', 'Tolypeutes tricinctus', 'Vulnerável', 'vulneravel', 'Mamífero', 'Nordeste, Centro-Oeste', 'Caatinga, Cerrado', 'https://inaturalist-open-data.s3.amazonaws.com/photos/51545670/original.jpg', 'Caatinga e áreas de vegetação seca.', 'Quando ameaçado, pode se enrolar completamente formando uma bola.', 'É uma das poucas espécies de tatu capazes de se enrolar completamente.', 'Formigas, cupins, pequenos invertebrados e frutos.', 'Caça e perda de habitat.', 39717, 'iNaturalist', '(c) Allan Hopkins, some rights reserved (CC BY-NC-ND) | cc-by-nc-nd | https://www.inaturalist.org/observations/32845131'),
(10, 'Carcará', 'Caracara plancus', 'Pouco preocupante', 'pouco-preocupante', 'Ave', 'Norte, Nordeste, Centro-Oeste, Sudeste, Sul', 'Amazônia, Caatinga, Cerrado, Pantanal, Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/62917202/original.jpeg', 'Campos, áreas abertas e regiões de vegetação variada.', 'É oportunista e consegue aproveitar diferentes fontes de alimento.', 'É conhecido por sua capacidade de aproveitar diferentes tipos de alimento.', 'Pequenos animais, carniça, ovos, insetos e frutos.', 'Alterações ambientais e redução de habitat.', 226367, 'iNaturalist', '(c) Coleen Lawlor, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/39644894'),
(11, 'Cobra-Coral', 'Micrurus corallinus', 'Pouco preocupante', 'pouco-preocupante', 'Réptil', 'Nordeste, Sudeste, Sul', 'Caatinga, Mata Atlântica, Pampa', 'https://inaturalist-open-data.s3.amazonaws.com/photos/617927419/original.jpg', 'Florestas, áreas de serrapilheira e regiões úmidas.', 'É discreta e passa grande parte do tempo escondida.', 'Possui padrão de cores característico formado por anéis.', 'Pequenos répteis, anfíbios e outros animais.', 'Destruição do habitat e perseguição humana.', 81921, 'iNaturalist', '(c) Claudio Martins de Souza, some rights reserved (CC BY-SA) | cc-by-sa | https://www.inaturalist.org/observations/339655959'),
(12, 'Jararaca', 'Bothrops jararaca', 'Pouco preocupante', 'pouco-preocupante', 'Réptil', 'Sudeste, Sul', 'Mata Atlântica, Pampa', 'https://inaturalist-open-data.s3.amazonaws.com/photos/461289779/original.jpeg', 'Matas, áreas rurais e regiões de vegetação densa.', 'É predominantemente noturna e utiliza camuflagem para capturar suas presas.', 'Seu veneno possui grande importância para pesquisas médicas.', 'Pequenos mamíferos, aves, anfíbios e outros animais.', 'Desmatamento e conflitos com seres humanos.', 81229, 'iNaturalist', '(c) Rogerio Dias, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/257177128'),
(13, 'Veado-Campeiro', 'Ozotoceros bezoarticus', 'Vulnerável', 'vulneravel', 'Mamífero', 'Centro-Oeste, Sudeste, Sul', 'Cerrado, Pantanal, Pampa', 'https://inaturalist-open-data.s3.amazonaws.com/photos/59434566/original.jpg', 'Campos naturais e áreas abertas.', 'Vive em pequenos grupos e se alimenta principalmente durante períodos de menor calor.', 'É adaptado a ambientes abertos e possui grande capacidade de deslocamento.', 'Gramíneas, folhas e outras plantas.', 'Perda de habitat, caça e expansão agropecuária.', 73016, 'iNaturalist', '(c) constanzamcl, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/37486071'),
(14, 'Gato-do-Mato', 'Leopardus tigrinus', 'Vulnerável', 'vulneravel', 'Mamífero', 'Norte, Nordeste, Centro-Oeste, Sudeste, Sul', 'Amazônia, Caatinga, Cerrado, Mata Atlântica', 'https://inaturalist-open-data.s3.amazonaws.com/photos/342548847/original.jpg', 'Florestas e áreas de vegetação densa.', 'É solitário e possui hábitos principalmente noturnos.', 'É um dos menores felinos silvestres encontrados no Brasil.', 'Pequenos mamíferos, aves, répteis e anfíbios.', 'Desmatamento, fragmentação do habitat e caça.', 35163, 'iNaturalist', '(c) mauricio_guitar, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/194814424'),
(15, 'Sapo-Cururu', 'Rhinella icterica', 'Pouco preocupante', 'pouco-preocupante', 'Anfíbio', 'Sudeste, Sul', 'Mata Atlântica, Pampa', 'https://inaturalist-open-data.s3.amazonaws.com/photos/339638733/original.jpg', 'Áreas úmidas, florestas e ambientes próximos a corpos d’água.', 'Possui hábitos principalmente noturnos e utiliza áreas próximas à água para reprodução.', 'Possui glândulas que produzem substâncias utilizadas como defesa.', 'Insetos e outros pequenos invertebrados.', 'Poluição da água, perda de habitat e doenças que afetam anfíbios.', 78979, 'iNaturalist', '(c) andrefrancis, some rights reserved (CC BY-NC) | cc-by-nc | https://www.inaturalist.org/observations/193347176'),
